nodes = data['nodes']
edges = data['edges']
levels = {}
remaining = nodes
while len(remaining) > 0:
    changed = False
    for node in remaining:
        preds = [edge['u'] for edge in edges if edge['v'] == node]
        ready = all(pred in keys(levels) for pred in preds)
        if ready:
            lvl = max([levels[pred] + 1 for pred in preds] or [0])
            levels = putmap(levels, node, lvl)
            changed = True
    remaining = [node for node in nodes if node not in keys(levels)]
    if not changed:
        break
maxlevel = max(list(levels.values()) or [])
layers = [[node for node in sorted(nodes) if levels[node] == lvl] for lvl in range(maxlevel + 1)]
